// Gap detector: one thread pinned per CPU spins reading CLOCK_MONOTONIC and
// its own CLOCK_THREAD_CPUTIME_ID; a gap is a jump of the monotonic clock
// between two reads. Reports per CPU: gaps >= 0.1/1/5/10/20 ms, the largest,
// and how much of the gap time the thread CPU clock counted as its own.
#define _GNU_SOURCE
#include <pthread.h>
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
static double secs;
static double now(clockid_t c){struct timespec t;clock_gettime(c,&t);return t.tv_sec*1e3+t.tv_nsec/1e6;}
static void* run(void* a){
  long cpu=(long)a; cpu_set_t s; CPU_ZERO(&s); CPU_SET(cpu,&s); pthread_setaffinity_np(pthread_self(),sizeof s,&s);
  long b[5]={0}, bo[5]={0}; double mxo=0; double th[5]={0.1,1,5,10,20}, mx=0, gapsum=0, gapcpu=0;
  double t0=now(CLOCK_MONOTONIC), last=t0, lastc=now(CLOCK_THREAD_CPUTIME_ID);
  while(last-t0<secs*1e3){
    double t=now(CLOCK_MONOTONIC), c=now(CLOCK_THREAD_CPUTIME_ID), g=t-last;
    if(g>=0.1){ double dc=c-lastc; int on=dc>=0.9*g; for(int i=0;i<5;i++) if(g>=th[i]) {b[i]++; if(on) bo[i]++;} if(g>mx)mx=g; if(on&&g>mxo)mxo=g; gapsum+=g; gapcpu+=dc; }
    last=t; lastc=c;
  }
  double cpuT=now(CLOCK_THREAD_CPUTIME_ID), wall=last-t0;
  printf("cpu%ld wall=%.0fms threadcpu=%.0fms gaps>=0.1ms:%ld >=1:%ld >=5:%ld >=10:%ld >=20:%ld max=%.2fms | on_thread_clock: >=1:%ld >=5:%ld >=10:%ld >=20:%ld max=%.2fms | gaptime=%.1fms of_which_on_thread_clock=%.1fms\n",cpu,wall,cpuT,b[0],b[1],b[2],b[3],b[4],mx,bo[1],bo[2],bo[3],bo[4],mxo,gapsum,gapcpu);
  return 0;
}
int main(int c,char**v){ secs=c>1?atof(v[1]):30; int n=c>2?atoi(v[2]):4; pthread_t t[64]; for(long i=0;i<n;i++) pthread_create(&t[i],0,run,(void*)i); for(int i=0;i<n;i++) pthread_join(t[i],0); }

