// One spinner per CPU; prints every gap >= 5 ms as "cpu start_ms end_ms".
#define _GNU_SOURCE
#include <pthread.h>
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
static double secs;
static double now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec*1e3+t.tv_nsec/1e6;}
static void* run(void* a){
  long cpu=(long)a; cpu_set_t s; CPU_ZERO(&s); CPU_SET(cpu,&s); pthread_setaffinity_np(pthread_self(),sizeof s,&s);
  double t0=now(), last=t0;
  while(last-t0<secs*1e3){ double t=now(); if(t-last>=5) printf("%ld %.3f %.3f\n",cpu,last,t); last=t; }
  return 0;
}
int main(int c,char**v){ secs=atof(v[1]); int n=atoi(v[2]); setvbuf(stdout,0,_IOLBF,0); pthread_t t[64]; for(long i=0;i<n;i++) pthread_create(&t[i],0,run,(void*)i); for(int i=0;i<n;i++) pthread_join(t[i],0); }
